using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
class InsulationRollQuantity {
 public double NetArea,RollArea,PurchaseArea;public int Rolls;
 public static InsulationRollQuantity Calculate(double area,double width,double length){RoofMath.Positive(width,length);if(double.IsNaN(area)||double.IsInfinity(area)||area<0)throw new Exception("Invalid insulation area.");double rollArea=width*length;int rolls=area==0?0:RoofMath.Ceil(area/rollArea);return new InsulationRollQuantity{NetArea=area,RollArea=rollArea,Rolls=rolls,PurchaseArea=rolls*rollArea};}
}
partial class ProgramOfWorksForm {
 internal static readonly string[] InsulationTypes={"8mm thk. Double-Sided Aluminum Foil Bubble Insulation","10mm thk. Aluminum Foil Double Faced Polyethylene Foam Insulation"};
 DataGridView insulationRolls;NumericUpDown accessoryLap;
 void AddInsulationSettings(){insulationRolls=Grid(new[]{"Insulation type","Roll width m","Roll length m","Roll area m2"},3);insulationRolls.AllowUserToAddRows=false;insulationRolls.AllowUserToDeleteRows=false;insulationRolls.Columns[0].ReadOnly=true;insulationRolls.Columns[0].Width=570;foreach(string type in InsulationTypes)insulationRolls.Rows.Add(type,"","","");var start=tabs.TabPages.Cast<TabPage>().First(p=>p.Text=="Roofing Start");var profilesPage=new TabPage("Roof profiles");start.Controls.Remove(roofProfiles);profilesPage.Controls.Add(roofProfiles);var insulationPage=new TabPage("Insulation roll settings");insulationPage.Controls.Add(insulationRolls);var pages=new TabControl{Dock=DockStyle.Fill};pages.TabPages.Add(profilesPage);pages.TabPages.Add(insulationPage);start.Controls.Add(pages);pages.BringToFront();var help=new Label{Dock=DockStyle.Top,Height=60,Padding=new Padding(10),Text="Enter supplier roll WIDTH and LENGTH in metres for each insulation type used. Whole rolls are rounded up after pooling the net roof area of the same type. No overlap/waste factor is assumed."};insulationPage.Controls.Add(help);var accessoryPage=new TabPage("Flashing & gutter settings");var content=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),FlowDirection=FlowDirection.TopDown};content.Controls.Add(new Label{Text="Commercial piece length: 2.44 m (fixed)",Width=700,Height=35});content.Controls.Add(new Label{Text="Default lap for flashing, gutters and ridge rolls (mm)",Width=700,Height=30});accessoryLap=new NumericUpDown{Minimum=0,Maximum=1000,Value=150,DecimalPlaces=0,Width=220};accessoryLap.ValueChanged+=(s,e)=>{if(!filling)Recalculate();};content.Controls.Add(accessoryLap);content.Controls.Add(new Label{Text="150 mm is an estimating default. Confirm lap against the approved project detail. End closures use zero lap.",Width=730,Height=65});accessoryPage.Controls.Add(content);pages.TabPages.Add(accessoryPage);AddCombo(roofSheets,11,"Insulation type",InsulationTypes);roofSheets.Columns[11].Width=310;}
 List<object[]> InsulationSummary(){var rows=new List<object[]>();for(int i=0;i<InsulationTypes.Length;i++){string type=InsulationTypes[i];double area=roofSheets.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is RoofSheetQuantity&&Cell(r,11)==type).Sum(r=>((RoofSheetQuantity)r.Tag).Insulation);var settings=insulationRolls.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>Cell(r,0)==type);if(settings==null)throw new Exception("Missing insulation roll settings: "+type);if(area==0){rows.Add(new object[]{type+" net area",0.0,"m2"});continue;}var result=InsulationRollQuantity.Calculate(area,Number(settings,1),Number(settings,2));settings.Cells[3].Value=result.RollArea.ToString("0.00");rows.Add(new object[]{type+" net area",result.NetArea,"m2"});rows.Add(new object[]{type+" purchase coverage",result.PurchaseArea,"m2"});}return rows;}
}
}

